CREATE TABLE IF NOT EXISTS insurance_regimes (id SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, code VARCHAR(30) NOT NULL UNIQUE, name VARCHAR(80) NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS eps (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, code VARCHAR(30) NOT NULL UNIQUE, name VARCHAR(150) NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS eps_plans (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, eps_id BIGINT UNSIGNED NOT NULL, regime_id SMALLINT UNSIGNED NOT NULL, code VARCHAR(50) NOT NULL, name VARCHAR(150) NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, UNIQUE KEY uq_eps_plan_code(eps_id,code), FOREIGN KEY(eps_id) REFERENCES eps(id), FOREIGN KEY(regime_id) REFERENCES insurance_regimes(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS user_insurance_affiliations (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, plan_id BIGINT UNSIGNED NOT NULL, membership_number VARCHAR(80) NOT NULL, is_current BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_user_membership(user_id,plan_id,membership_number), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(plan_id) REFERENCES eps_plans(id), INDEX ix_user_insurance_current(user_id,is_current)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS locations (id SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, code VARCHAR(30) NOT NULL UNIQUE, name VARCHAR(180) NOT NULL, address VARCHAR(255) NOT NULL, city VARCHAR(100) NOT NULL, department VARCHAR(100) NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS specialties (id SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, code VARCHAR(50) NOT NULL UNIQUE, name VARCHAR(150) NOT NULL UNIQUE, appointment_duration_minutes SMALLINT UNSIGNED NOT NULL, is_general BOOLEAN NOT NULL DEFAULT FALSE, requires_admin_approval BOOLEAN NOT NULL DEFAULT TRUE, active BOOLEAN NOT NULL DEFAULT TRUE, CONSTRAINT ck_specialty_duration_v2 CHECK (appointment_duration_minutes IN (30,60))) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS professionals (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL UNIQUE, professional_code VARCHAR(40) NOT NULL UNIQUE, license_number VARCHAR(80) NOT NULL UNIQUE, active BOOLEAN NOT NULL DEFAULT TRUE, FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS professional_specialties (professional_id BIGINT UNSIGNED NOT NULL, specialty_id SMALLINT UNSIGNED NOT NULL, is_primary BOOLEAN NOT NULL DEFAULT FALSE, active BOOLEAN NOT NULL DEFAULT TRUE, PRIMARY KEY(professional_id,specialty_id), FOREIGN KEY(professional_id) REFERENCES professionals(id) ON DELETE CASCADE, FOREIGN KEY(specialty_id) REFERENCES specialties(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS professional_locations (professional_id BIGINT UNSIGNED NOT NULL, location_id SMALLINT UNSIGNED NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, PRIMARY KEY(professional_id,location_id), FOREIGN KEY(professional_id) REFERENCES professionals(id) ON DELETE CASCADE, FOREIGN KEY(location_id) REFERENCES locations(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS appointment_statuses (id SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, code VARCHAR(40) NOT NULL UNIQUE, name VARCHAR(80) NOT NULL, is_terminal BOOLEAN NOT NULL DEFAULT FALSE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS appointments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, patient_user_id BIGINT UNSIGNED NOT NULL, professional_id BIGINT UNSIGNED NOT NULL, location_id SMALLINT UNSIGNED NOT NULL, specialty_id SMALLINT UNSIGNED NOT NULL, insurance_affiliation_id BIGINT UNSIGNED NULL, status_id SMALLINT UNSIGNED NOT NULL, reason VARCHAR(500) NULL, scheduled_start_at DATETIME NOT NULL, scheduled_end_at DATETIME NOT NULL, created_by_user_id BIGINT UNSIGNED NOT NULL, approved_by_user_id BIGINT UNSIGNED NULL, approved_at DATETIME NULL, FOREIGN KEY(patient_user_id) REFERENCES users(id), FOREIGN KEY(professional_id) REFERENCES professionals(id), FOREIGN KEY(location_id) REFERENCES locations(id), FOREIGN KEY(specialty_id) REFERENCES specialties(id), FOREIGN KEY(insurance_affiliation_id) REFERENCES user_insurance_affiliations(id) ON DELETE SET NULL, FOREIGN KEY(status_id) REFERENCES appointment_statuses(id), FOREIGN KEY(created_by_user_id) REFERENCES users(id), FOREIGN KEY(approved_by_user_id) REFERENCES users(id), INDEX ix_appointments_professional(professional_id,scheduled_start_at), INDEX ix_appointments_status(status_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS availability_blocks (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, professional_id BIGINT UNSIGNED NOT NULL, location_id SMALLINT UNSIGNED NOT NULL, available_date DATE NOT NULL, start_time TIME NOT NULL, end_time TIME NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, FOREIGN KEY(professional_id) REFERENCES professionals(id), FOREIGN KEY(location_id) REFERENCES locations(id), INDEX ix_availability_prof_date(professional_id,available_date,start_time)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS professional_slots (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, availability_block_id BIGINT UNSIGNED NOT NULL, start_at DATETIME NOT NULL, end_at DATETIME NOT NULL, appointment_id BIGINT UNSIGNED NULL, FOREIGN KEY(availability_block_id) REFERENCES availability_blocks(id), FOREIGN KEY(appointment_id) REFERENCES appointments(id) ON DELETE SET NULL, UNIQUE KEY uq_block_slot(availability_block_id,start_at), INDEX ix_slots_lookup(start_at,appointment_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS appointment_status_history (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, appointment_id BIGINT UNSIGNED NOT NULL, status_id SMALLINT UNSIGNED NOT NULL, changed_by_user_id BIGINT UNSIGNED NULL, change_source VARCHAR(20) NOT NULL, reason VARCHAR(500) NULL, changed_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(appointment_id) REFERENCES appointments(id) ON DELETE CASCADE, FOREIGN KEY(status_id) REFERENCES appointment_statuses(id), FOREIGN KEY(changed_by_user_id) REFERENCES users(id), INDEX ix_status_history_appointment(appointment_id,changed_at)) ENGINE=InnoDB;
INSERT INTO insurance_regimes(code,name) VALUES ('PARTICULAR','Particular') ON DUPLICATE KEY UPDATE name=VALUES(name);
INSERT INTO eps(code,name,active) VALUES ('PARTICULAR_DEMO','Atención Particular Demo',TRUE) ON DUPLICATE KEY UPDATE name=VALUES(name),active=VALUES(active);
INSERT INTO eps_plans(eps_id,regime_id,code,name,active) SELECT e.id,r.id,'PARTICULAR','Plan Particular Demo',TRUE FROM eps e JOIN insurance_regimes r WHERE e.code='PARTICULAR_DEMO' AND r.code='PARTICULAR' ON DUPLICATE KEY UPDATE name=VALUES(name),active=VALUES(active);
INSERT INTO locations(id,code,name,address,city,department,active) VALUES (1,'HIC','Hospital Internacional de Colombia (HIC)','Km 7 Autopista Bucaramanga - Piedecuesta, Valle de Menzulí','Piedecuesta','Santander',TRUE),(2,'ICV','Fundación Cardiovascular de Colombia - Instituto Cardiovascular','Calle 155A No. 23-58, Urbanización El Bosque','Floridablanca','Santander',TRUE) ON DUPLICATE KEY UPDATE name=VALUES(name),address=VALUES(address),city=VALUES(city),department=VALUES(department),active=VALUES(active);
INSERT INTO appointment_statuses(id,code,name,is_terminal) VALUES (1,'REQUESTED','Solicitada',FALSE),(2,'APPROVED','Aprobada',FALSE),(3,'REJECTED','Rechazada',TRUE),(4,'CANCELLED','Cancelada',TRUE),(5,'COMPLETED','Completada',TRUE),(6,'NO_SHOW','No asistió',TRUE) ON DUPLICATE KEY UPDATE name=VALUES(name),is_terminal=VALUES(is_terminal);
INSERT INTO specialties(code,name,appointment_duration_minutes,is_general,requires_admin_approval,active) VALUES ('MEDICINA_GENERAL','Medicina General',30,TRUE,FALSE,TRUE) ON DUPLICATE KEY UPDATE name=VALUES(name),active=VALUES(active);
